import json,re
from pathlib import Path
r=json.loads(Path('furniture-editor/library/models/house-interior/conversion-report.json').read_text())
translations={'Bathroom_Bathtub':'Badkar','Bathroom_Mirror':'Badrumsspegel','Bathroom_Shower':'Dusch','Bathroom_Sink':'Handfat','Bathroom_ToiletPaperPile':'Toalettpappersrullar','Bathroom_ToiletPaper':'Toalettpapper','Bathroom_Toilet':'Toalett','Bathroom_Towel':'Handduk','Bathroom_WashingMachine':'Tvättmaskin','Bed_Bunk':'Våningssäng','Bed_King':'Dubbelsäng','Bed_Single':'Enkelsäng','Bookshelf':'Bokhylla','Carpet_Round':'Rund matta','Carpet':'Matta','Chair':'Stol','Column_Round':'Rund pelare','Column_SquareBig':'Stor fyrkantig pelare','Column_SquareSmall':'Liten fyrkantig pelare','Couch_Large':'Stor soffa','Couch_Medium':'Soffa','Couch_Small':'Fåtölj','Couch_L':'Hörnsoffa','Curtains_Double':'Dubbla gardiner','Curtains_Single':'Gardin','Door_Double':'Dubbeldörr','Door':'Dörrmodell','Drawer':'Byrå','Fireplace':'Öppen spis','Fork':'Gaffel','Houseplant':'Krukväxt','Kitchen_1Drawers':'Köksbänk med låda','Kitchen_2Drawers':'Köksbänk med två lådor','Kitchen_3Drawers':'Köksbänk med tre lådor','Kitchen_CabinetSmall':'Litet köksskåp','Kitchen_Cabinet':'Köksskåp','Kitchen_Fridge':'Kylskåp','Kitchen_Oven_Large':'Stor ugn','Kitchen_Oven':'Ugn','Kitchen_Sink':'Diskho','Knife':'Kniv','Light_CeilingSingle':'Enkel taklampa','Light_Ceiling':'Taklampa','Light_Chandelier':'Ljuskrona','Light_Cube':'Kubformad lampa','Light_Desk':'Bordslampa','Light_Floor':'Golvlampa','Light_Icosahedron':'Geometrisk lampa','Light_Small':'Liten lampa','Light_Stand':'Lampa på fot','NightStand':'Nattduksbord','Plate':'Tallrik','Shelf_Large':'Stor hylla','Shelf_Small':'Liten hylla','Shelf':'Hylla','Spoon':'Sked','Stool':'Pall','Table_RoundLarge':'Stort runt bord','Table_RoundSmall':'Litet runt bord','Trashcan_Cylindric':'Rund papperskorg','Trashcan_Green':'Grön papperskorg','Trashcan_Large':'Stor papperskorg','Trashcan_Small':'Liten papperskorg','Window_Large':'Stort fönster','Window_Round':'Runt fönster','Window_Small':'Litet fönster'}
rows=[]
for f in r['files']:
 if f['status']!='PASS':continue
 stem=Path(f['source']).stem;key=next((k for k in sorted(translations,key=len,reverse=True) if stem.startswith(k)),stem)
 tail=stem[len(key):].replace('_',' ').strip();name=translations.get(key,key)+(' '+tail if tail else '')
 cat='badrum' if stem.startswith('Bathroom') else 'kok' if stem.startswith(('Kitchen','Plate','Fork','Knife','Spoon')) else 'stolar' if stem.startswith(('Chair','Stool','Couch')) else 'bord' if stem.startswith(('Table','NightStand')) else 'kontor' if stem.startswith(('Bookshelf','Drawer','Shelf')) else 'dekor'
 w,d,h=f['dimensionsXYZ'];decor=stem.startswith(('Window','Door'))
 placement='wall' if 'Mirror' in stem else 'countertop' if stem.startswith(('Plate','Fork','Knife','Spoon','Light_Desk','Bathroom_ToiletPaper')) else 'floor'
 rows.append(dict(id='onboard:house-'+stem.lower().replace('_','-'),name=name+(' · dekor' if decor else ''),category=cat,kind='prop',width=round(w,4),depth=round(d,4),height=round(h,4),model=stem,pack='house-interior',url='./library/models/house-interior/'+f['output'],thumb='./library/thumbs/house-interior/'+stem+'.webp',placement=placement,staticOnly=True,keywords=stem.replace('_',' ')+' husinredning',license='Ägarens modeller · offentlig publicering godkänd 2026-11-01',source='capstere/onboard@ccaf58d · House interior Blends',sha256=f['sha256']))
Path('furniture-editor/library/house-catalog.mjs').write_text('/** Measured GLB derivatives. Owner confirmed ownership/publication on 2026-11-01. Original BLEND files unchanged. */\nexport const HOUSE_LIBRARY=Object.freeze('+json.dumps(rows,ensure_ascii=False,indent=2)+'.map(Object.freeze));\n')
for row in rows:
 if 'Mirror' in row['model']: row['wallFacing']='+z'
Path('furniture-editor/library/house-catalog.mjs').write_text('/** Owner-authorized static models, measured and round-trip checked in Blender 4.5.3. */\nexport const HOUSE_LIBRARY=Object.freeze('+json.dumps(rows,ensure_ascii=False,indent=2)+'.map(Object.freeze));\n')
print('Catalog entries',len(rows))
